#!/usr/bin/env python3
"""Test host reachability matrix."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

NON_GUEST = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}

GUEST = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

ALL_HOSTS = {**NON_GUEST, **GUEST}

def ping_from(src_name, src_mgmt, targets):
    """Ping all targets from src_name. Returns list of (src, dst_name, dst_ip, success)."""
    results = []
    try:
        conn = ConnectHandler(host=src_mgmt, device_type="linux", username="root", password="alpine")
        for dst_name, dst_ip in targets:
            out = conn.send_command(f"ping -c 2 -W 2 {dst_ip}", read_timeout=15)
            success = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
            results.append((src_name, dst_name, dst_ip, success))
        # Also test internet
        for ip in ["8.8.8.8", "1.1.1.1"]:
            out = conn.send_command(f"ping -c 2 -W 2 {ip}", read_timeout=15)
            success = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
            results.append((src_name, ip, ip, success))
        conn.disconnect()
    except Exception as e:
        results.append((src_name, "CONNECTION_ERROR", "", False))
    return results

# Build target lists for each host
all_results = []
with ThreadPoolExecutor(max_workers=10) as pool:
    futures = []
    for src_name, (src_mgmt, src_lab) in ALL_HOSTS.items():
        # Build target list: all other hosts + internet
        targets = []
        for dst_name, (_, dst_lab) in ALL_HOSTS.items():
            if dst_name != src_name:
                targets.append((dst_name, dst_lab))
        futures.append(pool.submit(ping_from, src_name, src_mgmt, targets))

    for f in as_completed(futures):
        all_results.extend(f.result())

# Classify results
print("=" * 70)
print("HOST REACHABILITY MATRIX")
print("=" * 70)

# Non-guest to non-guest (should all pass)
ng_ng_fail = []
ng_ng_pass = 0
for src, dst, ip, ok in all_results:
    if src in NON_GUEST and dst in NON_GUEST:
        if ok:
            ng_ng_pass += 1
        else:
            ng_ng_fail.append(f"  {src} -> {dst} ({ip}) FAILED")

print(f"\nNon-guest to non-guest: {ng_ng_pass} pass, {len(ng_ng_fail)} fail (expected: 56 pass)")
for f in ng_ng_fail:
    print(f)

# Guest to guest (should pass)
g_g_fail = []
g_g_pass = 0
for src, dst, ip, ok in all_results:
    if src in GUEST and dst in GUEST:
        if ok:
            g_g_pass += 1
        else:
            g_g_fail.append(f"  {src} -> {dst} ({ip}) FAILED")

print(f"\nGuest to guest: {g_g_pass} pass, {len(g_g_fail)} fail (expected: 2 pass)")
for f in g_g_fail:
    print(f)

# Guest to non-guest (should fail - policy)
g_ng_pass_bad = []
g_ng_drop = 0
for src, dst, ip, ok in all_results:
    if src in GUEST and dst in NON_GUEST:
        if ok:
            g_ng_pass_bad.append(f"  {src} -> {dst} ({ip}) PASSED (should be blocked)")
        else:
            g_ng_drop += 1

print(f"\nGuest to non-guest: {g_ng_drop} blocked, {len(g_ng_pass_bad)} leaked (expected: 16 blocked)")
for f in g_ng_pass_bad:
    print(f)

# Non-guest to guest (should fail - policy)
ng_g_pass_bad = []
ng_g_drop = 0
for src, dst, ip, ok in all_results:
    if src in NON_GUEST and dst in GUEST:
        if ok:
            ng_g_pass_bad.append(f"  {src} -> {dst} ({ip}) PASSED (should be blocked)")
        else:
            ng_g_drop += 1

print(f"\nNon-guest to guest: {ng_g_drop} blocked, {len(ng_g_pass_bad)} leaked (expected: 16 blocked)")
for f in ng_g_pass_bad:
    print(f)

# Internet reachability
inet_pass = 0
inet_fail = []
for src, dst, ip, ok in all_results:
    if dst in ["8.8.8.8", "1.1.1.1"]:
        if ok:
            inet_pass += 1
        else:
            inet_fail.append(f"  {src} -> {dst} FAILED")

print(f"\nInternet (8.8.8.8 + 1.1.1.1): {inet_pass} pass, {len(inet_fail)} fail (expected: 20 pass)")
for f in inet_fail:
    print(f)
