#!/usr/bin/env python3
"""Test guest isolation only."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

NON_GUEST = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
}

GUEST = {
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

def ping_test(src_name, src_mgmt, dst_name, dst_ip):
    try:
        conn = ConnectHandler(host=src_mgmt, device_type="linux", username="root", password="alpine")
        out = conn.send_command(f"ping -c 2 -W 2 {dst_ip}", read_timeout=15)
        conn.disconnect()
        success = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
        return (src_name, dst_name, dst_ip, success, out.strip().split('\n')[-1])
    except Exception as e:
        return (src_name, dst_name, dst_ip, False, str(e))

results = []
with ThreadPoolExecutor(max_workers=5) as pool:
    futures = []
    # Guest -> non-guest
    for sn, (sm, _) in GUEST.items():
        for dn, (_, dl) in NON_GUEST.items():
            futures.append(pool.submit(ping_test, sn, sm, dn, dl))
    # Non-guest -> guest
    for sn, (sm, _) in NON_GUEST.items():
        for dn, (_, dl) in GUEST.items():
            futures.append(pool.submit(ping_test, sn, sm, dn, dl))
    # Guest -> guest (should pass)
    for sn, (sm, _) in GUEST.items():
        for dn, (_, dl) in GUEST.items():
            if sn != dn:
                futures.append(pool.submit(ping_test, sn, sm, dn, dl))

    for f in as_completed(futures):
        results.append(f.result())

for src, dst, ip, ok, detail in sorted(results):
    status = "PASS" if ok else "DROP"
    print(f"{src:8s} -> {dst:8s} ({ip:12s}): {status}  [{detail}]")
